query.query:
query Scheduler($workcenterWhere:WorkcenterWhereInput, $distributionWhere:WorkOrderProcessDistributionWhereInput) {
  workcenter(where: $workcenterWhere) {
    edges {
      node {
        id
        name
        productionSetup {
          mode {
            name
            modeType {
              production
              maintenance
              changeover
              idle
              color
            }
          }
        }
        workcenterGroup {
          name
        }
        shiftGroup {
          id
          name
          shifts {
            edges { 
              node {  
                shift {
                  name
                  startAt
                  endAt
                  sunday
                  monday
                  tuesday
                  wednesday
                  thursday
                  friday
                  saturday
                }
              }
            }
          }
        }
        image {
          thumbnailUrl
        }
      }
    }
  }

  workOrderProcessDistribution(where: $distributionWhere) {
    edges {
      node {
        id
        number
        resourceId: workcenterId
        startDate: scheduledStartAt
        endDate: scheduledFinishAt
        requiredQuantity
        duration: plannedDuration
        distributionGroupId
        distributionGroup {
          id
          calendarEvent {
            id
            eventJson
          }
        }
        workOrderProcessDistributionStatus {
          name
          color
        }
        workOrderProcess {
          order
          process {
						code
          }
          workOrderId
          workOrder {
            number
            quantity
            workOrderPriority {
              color
              name
            }
          }
          productStrategyProcess {
            code
            workcenter {
              id
              code
            }
            alternateWorkcenters {
              edges {
                node {
                  workcenter {
                    id
                    code
                  }
                }
              }
            }
          }
          productStrategy {
            product {
              number
            }
          }
        }
      }
    }
  }
}

resources.__transform:
(
  $resources := [data.workcenter.edges.node
    ~> | $ | {
      "imageUrl": image.thumbnailUrl,
      "workcenterGroup": $coalesce([workcenterGroup, {
        "name": "(No Group)"
      }]),
      "calendar": shiftGroup.id,
      "allowOverlap": false,
      "metaHtml": $isNilOrEmpty(productionSetup.mode) 
        ? null
        : (
          $modeType := productionSetup.mode.modeType;

          $icon := $modeType.production
            ? 'circle-check'
            : $modeType.maintenance
            ? 'wrench'
            : $modeType.changeover
            ? 'exchange'
            : $modeType.idle
            ? 'ellipsis-h'
            : '';

          "<i style='color:" & $modeType.color & "' class='b-fa-solid b-fa-" & $icon & "'></i>&nbsp;&nbsp;" & productionSetup.mode.name
        )
  } |][
    $components.ScheduleFilterForm.data.scheduledWorkcentersOnly ? (
      $eventsByWorkcenter := $groupBy(
        [$$.data.workOrderProcessDistribution.edges.node[$isNotNilOrEmpty(startDate)]], 
        function($v) { $v.resourceId }
      );

      $isNotNilOrEmpty($lookup($eventsByWorkcenter, $.id))
    ) : true
  ];

  [$resources];
)

calendars.__transform:
(
  $convertDate := function($date) {
    $moment($date).tz("UTC").tz($momentTzGuess(), true)
  };

  $formatTime := function($date) {
    $moment($date).tz("UTC").tz($momentTzGuess(), true).format('HH:mm')
  };

  $formatDays := function($shift, $overnight) {
    $join([
      ($shift.sunday ? ($overnight ? 'monday' : 'sunday')),
      ($shift.monday ? ($overnight ? 'tuesday' : 'monday')),
      ($shift.tuesday ? ($overnight ? 'wednesday' : 'tuesday')),
      ($shift.wednesday ? ($overnight ? 'thursday' : 'wednesday')),
      ($shift.thursday ? ($overnight ? 'friday' : 'thursday')),
      ($shift.friday ? ($overnight ? 'saturday' : 'friday')),
      ($shift.saturday ? ($overnight ? 'sunday' : 'saturday'))
    ][$isNotNilOrEmpty($)], ',')
  };

  [
    $uniqBy(
      [data.workcenter.edges.node.shiftGroup],
      function($v) { $v.id }
    ).{
      "id": id,
      "name": name,
      "unspecifiedTimeIsWorking": false,
      "intervals": [shifts.edges.node.shift[
        $isNotNilOrEmpty(startAt)
          and $isNotNilOrEmpty(endAt)
      ].(
        $startAt := $convertDate(startAt);
        $endAt := $convertDate(endAt);

        {
          "name": name,
          "recurrentStartDate": "at " & $startAt.format('HH:mm') & " on " & $formatDays($, false),
          "recurrentEndDate": "at "& $endAt.format('HH:mm') & " on " & $formatDays($, $moment($endAt).isBefore($startAt)),
          "isWorking": true
        }
      )]
    }
  ]
)

dataTransform.transform:
[edges.node~>|$|(

$b := $coalesce([workOrderProcessDistributions.edges.node._aggregate.balanceQuantity.sum, 0]);
$r := $coalesce([workOrderProcessDistributions.edges.node._aggregate.requiredQuantity.sum, 0]);
$s := $coalesce([workOrderProcessDistributions.edges.node._aggregate.scrappedQuantity.sum,0]);
$op := $coalesce([productionOperators, 0]);
$st := setupRate >= 0 ? $sum(setupRate * 3600) : 0;
$mt := $b >= 0 and standardRate >0 ? $sum(($b / standardRate) * 3600) : 0;

{
"balance": $b,
"required": $r,
"scrapped": $s,
"laborTime": $sum($mt * $op),
"machTime": $mt,
"operators": $op,
"procTime": workOrderProcessStatusId = "New" and $mt > 0  ? $sum($mt + $st) : workOrderProcessStatusId != "New" or $mt = 0 ? $mt,
"workcenter": $isNilOrEmpty(workOrderProcessDistributions.edges.node.distributionGroup.workcenter.code) ? "Not Scheduled" : workOrderProcessDistributions.edges.node[0].distributionGroup.workcenter.code,
"schStart":   workOrderProcessDistributions.edges.node.scheduledStartAt,
"schEnd": workOrderProcessDistributions.edges.node.scheduledFinishAt
})|

]
